import sys,subprocess,time,json,hashlib
w=Path(__file__).resolve().parents[2];out=w/'sr-review/cli-recovered';out.mkdir(exist_ok=False);start=time.monotonic();cmd=[sys.executable,'-I','-B',str(w/'sr-review/code/cli_guarded.py'),str(w/'upload/I164-internal-status-return-correspondence-1(1).zip'),str(w/'sr-cli-root'),str(out/'recovery.json')];p=subprocess.run(cmd,capture_output=True);(out/'stdout').write_bytes(p.stdout);(out/'stderr').write_bytes(p.stderr)
